{"security_risk":"LOW","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type pg from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureRequestView {
  id: string;
  customerId: string;
  status: ErasureRequestRow['status'];
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export class ErasureRepository {
  /**
   * Either returns the existing erasure request bound to this idempotency key
   * (or the customer's single request) or creates a new one inside the same
   * transaction. Throws `404` when the customer does not exist for this
   * merchant and `409` when an idempotency key is reused across customers.
   */
  async requestErasure(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ request: ErasureRequestRow; created: boolean }> {
    return await transaction(async (client) => {
      const customer = await client.query(
        `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!customer.rowCount) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

      const existingKey = await client.query<{ customer_id: string; request_id: string }>(
        `SELECT customer_id, request_id FROM customers.erasure_idempotency_keys
         WHERE merchant_id=$1 AND key=$2 FOR UPDATE`,
        [merchantId, idempotencyKey],
      );
      if (existingKey.rows[0]) {
        if (existingKey.rows[0].customer_id !== customerId) {
          throw Object.assign(new Error('idempotency_key_reused'), { statusCode: 409 });
        }
        const request = await this.fetch(client, existingKey.rows[0].request_id);
        if (!request) throw Object.assign(new Error('erasure_request_missing'), { statusCode: 500 });
        return { request, created: false };
      }

      const existingForCustomer = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      let row = existingForCustomer.rows[0];
      let created = false;
      if (!row) {
        const inserted = await client.query<ErasureRequestRow>(
          `INSERT INTO customers.erasure_requests(merchant_id, customer_id) VALUES($1,$2) RETURNING *`,
          [merchantId, customerId],
        );
        row = inserted.rows[0]!;
        created = true;
      }
      await client.query(
        `INSERT INTO customers.erasure_idempotency_keys(merchant_id, key, customer_id, request_id)
         VALUES($1,$2,$3,$4)`,
        [merchantId, idempotencyKey, customerId, row.id],
      );
      return { request: row, created };
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  private async fetch(client: pg.PoolClient, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE id=$1`,
      [requestId],
    );
    return result.rows[0];
  }
}

export function toView(row: ErasureRequestRow): ErasureRequestView {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}"}

