import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface ClaimedErasure {
  id: string;
  merchant_id: string;
  customer_id: string;
  attempts: number;
}

export interface ErasureDocumentObject {
  object_key: string;
  document_type: string;
}

/**
 * Atomically claims a single pending or previously-failed erasure request.
 * Uses `FOR UPDATE SKIP LOCKED` so multiple workers can safely cooperate and
 * `processing` rows are immediately rejected by the `status IN ('pending','failed')`
 * predicate, giving every claim a fresh attempt counter.
 */
export async function claimErasureRequest(workerId: string, leaseSeconds = 120): Promise<ClaimedErasure | undefined> {
  return await transaction(async (client) => {
    const result = await client.query<ClaimedErasure>(
      `UPDATE customers.erasure_requests er
       SET status='processing', attempts=attempts+1, updated_at=now(),
           last_error=NULL
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed')
         ORDER BY updated_at
         FOR UPDATE SKIP LOCKED LIMIT 1
       )
       RETURNING id, merchant_id, customer_id, attempts`,
    );
    return result.rows[0];
  });
}

export async function markErasureCompleted(requestId: string): Promise<void> {
  await pool.query(
    `UPDATE customers.erasure_requests
     SET status='completed', completed_at=now(), updated_at=now(), last_error=NULL
     WHERE id=$1`,
    [requestId],
  );
}

export async function markErasureFailed(requestId: string, errorMessage: string, terminal: boolean): Promise<void> {
  await pool.query(
    `UPDATE customers.erasure_requests
     SET status=$2, updated_at=now(), last_error=$3
     WHERE id=$1`,
    [requestId, terminal ? 'failed' : 'pending', errorMessage.slice(0, 500)],
  );
}

export async function listCustomerDocuments(merchantId: string, customerId: string): Promise<ErasureDocumentObject[]> {
  const result = await pool.query<ErasureDocumentObject>(
    `SELECT object_key, document_type FROM operations.document_manifests
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return result.rows;
}

export async function deleteProjectionForCustomer(merchantId: string, customerId: string): Promise<void> {
  await pool.query(
    `UPDATE customers.customers SET status='deleted', updated_at=now()
     WHERE merchant_id=$1 AND id=$2 AND status<>'deleted'`,
    [merchantId, customerId],
  );
}"}

{"security_risk":"LOW","summary":"Create erasure cleanup logic","command":"create","path":"/workspace/source/apps/erasure-worker/src/cleanup.ts","file_text":"import type pg from 'pg';
import { transaction } from '../../../packages/database/src/pool.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { redis } from '../../../packages/redis/src/client.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import type { ClaimedErasure, ErasureDocumentObject } from './repository.js';

const ANONYMIZED_CUSTOMER_EMAIL_PREFIX = 'redacted+';

function anonymizedEmailSuffix(customerId: string): string {
  return customerId.replaceAll('-', '').slice(0, 12).toLowerCase();
}

function anonymizedEmailFor(customerId: string): string {
  return `${ANONYMIZED_CUSTOMER_EMAIL_PREFIX}${anonymizedEmailSuffix(customerId)}@deleted.local`;
}

function anonymizedExternalReference(customerId: string): string {
  return `redacted_${anonymizedEmailSuffix(customerId)}`;
}

function anonymizedDisplayName(customerId: string): string {
  return `Deleted Customer (${anonymizedEmailSuffix(customerId)})`;
}

/**
 * Returns the set of distinct email destinations that have been recorded for
 * this customer across PayFlow's delivery tables. Captured messages addressed
 * to those destinations are removed from Mailpit so the deleted subject no
 * longer receives PayFlow-controlled mail.
 */
async function scrubNotificationDestinations(client: pg.PoolClient, merchantId: string, customerId: string): Promise<string[]> {
  const result = await client.query<{ destination: string | null }>(
    `SELECT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL
     UNION
     SELECT destination FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL
     UNION
     SELECT destination FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL`,
    [merchantId, customerId],
  );
  const destinations = [...new Set(result.rows.map((row) => row.destination).filter((value): value is string => Boolean(value)))];
  await client.query(
    `UPDATE operations.email_deliveries SET destination=NULL WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.notifications SET destination=NULL WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.notification_preferences SET destination=NULL, enabled=false, updated_at=now()
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.analytics_events SET email=NULL WHERE merchant_id=$1 AND customer_id=$2 AND email IS NOT NULL`,
    [merchantId, customerId],
  );
  return destinations;
}

async function redactPendingOutboxPayloads(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE operations.outbox_events
     SET payload=jsonb_build_object('redacted', true, 'reason', 'erasure_in_progress')
     WHERE merchant_id=$1 AND aggregate_id=$2 AND status='pending'
       AND (payload ? 'email' OR payload ? 'customerEmail' OR payload ? 'customerSnapshot'
            OR payload ? 'billingSnapshot' OR payload ? 'destination')`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.outbox_events SET status='cancelled'
     WHERE merchant_id=$1 AND aggregate_id=$2 AND status='pending'
       AND event_type IN ('customer.created.v1','customer.updated.v1','customer.deleted.v1',
                          'customer.contact.changed.v1','customer.address.changed.v1',
                          'customer.payment_method.attached.v1','support.message.created.v1',
                          'customer.import.recorded.v1')`,
    [merchantId, customerId],
  );
}

async function redactPendingJobs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE operations.jobs
     SET status='cancelled', available_at=now(), last_error='cancelled_for_erasure'
     WHERE merchant_id=$1 AND status<>'completed'
       AND payload->>'customerId'=$2`,
    [merchantId, customerId],
  );
}

async function scrubFinancialRecords(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE payments.payment_intents
     SET customer_snapshot=jsonb_build_object('redacted', true)::jsonb
     WHERE merchant_id=$1 AND customer_id=$2
       AND customer_snapshot IS NOT NULL
       AND NOT (customer_snapshot ? 'redacted')`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE payments.refunds SET customer_email=NULL
     WHERE merchant_id=$1 AND payment_intent_id IN (
       SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
     ) AND customer_email IS NOT NULL`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE payments.invoices
     SET billing_snapshot=jsonb_build_object('redacted', true)::jsonb
     WHERE merchant_id=$1 AND customer_id=$2
       AND billing_snapshot IS NOT NULL
       AND NOT (billing_snapshot ? 'redacted')`,
    [merchantId, customerId],
  );
}

async function scrubSupportData(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE customers.support_messages
     SET body='[redacted due to data deletion request]'
     WHERE merchant_id=$1 AND author_id=$2 AND author_type='customer' AND body<>'[redacted due to data deletion request]'`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM customers.support_participants
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
}

async function scrubDirectCustomerTables(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(
    `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`,
    [merchantId, customerId],
  );
}

async function anonymizeCustomerRow(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  const email = anonymizedEmailFor(customerId);
  const externalReference = anonymizedExternalReference(customerId);
  const displayName = anonymizedDisplayName(customerId);
  await client.query(
    `UPDATE customers.customers
     SET email=$3, name=$4, external_reference=$5, phone=NULL,
         metadata='{}'::jsonb, status='deleted', updated_at=now(), version=version+1
     WHERE merchant_id=$1 AND id=$2 AND status<>'deleted'`,
    [merchantId, customerId, email, displayName, externalReference],
  );
}

async function redactAuditLogs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE platform.audit_logs
     SET metadata=jsonb_build_object('redacted', true)::jsonb
     WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2
       AND NOT (metadata ? 'redacted')`,
    [merchantId, customerId],
  );
}

async function detachDocumentManifests(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureDocumentObject[]> {
  const listed = await client.query<ErasureDocumentObject>(
    `SELECT object_key, document_type FROM operations.document_manifests
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.document_manifests SET customer_id=NULL
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return listed.rows;
}

async function deleteCustomerObjects(objects: ErasureDocumentObject[]): Promise<void> {
  for (const object of objects) {
    try {
      await objectStore.removeObject(DOCUMENT_BUCKET, object.object_key);
    } catch (error) {
      logger.warn({ error, objectKey: object.object_key }, 'failed to remove erasure document object');
    }
  }
}

async function deleteCustomerProjections(merchantId: string, customerId: string): Promise<void> {
  await redis.del(`merchant:${merchantId}:customer:${customerId}`);
  await redis.del(`merchant:${merchantId}:customer:${customerId}:activity`);
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
  } catch (error) {
    const status = (error as { statusCode?: number }).statusCode;
    if (status !== 404) logger.warn({ error, merchantId, customerId }, 'failed to remove opensearch customer projection');
  }
}

async function scrubCustomerImports(client: pg.PoolClient, merchantId: string, customerId: string): Promise<string[]> {
  const imports = await client.query<{ object_key: string }>(
    `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1 AND customer_id=$2 AND object_key IS NOT NULL`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE customers.customer_imports SET object_key=NULL, status='anonymized'
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return imports.rows.map((row) => row.object_key);
}

/**
 * Executes the full privacy-aware deletion flow for a single customer inside
 * one transactional boundary, then performs the irreversible external cleanup
 * (MinIO, Redis, OpenSearch, Mailpit). Every step is written to be safely
 * re-runnable: a worker that crashes mid-way will resume on a fresh claim and
 * converge on the same end state without exposing customer data again.
 */
export async function processErasure(request: ClaimedErasure): Promise<void> {
  const { merchant_id: merchantId, customer_id: customerId } = request;
  let documents: ErasureDocumentObject[] = [];
  let importObjects: string[] = [];
  let mailDestinations: string[] = [];
  await transaction(async (client) => {
    await scrubDirectCustomerTables(client, merchantId, customerId);
    mailDestinations = await scrubNotificationDestinations(client, merchantId, customerId);
    await redactPendingOutboxPayloads(client, merchantId, customerId);
    await redactPendingJobs(client, merchantId, customerId);
    await scrubFinancialRecords(client, merchantId, customerId);
    await scrubSupportData(client, merchantId, customerId);
    await redactAuditLogs(client, merchantId, customerId);
    documents = await detachDocumentManifests(client, merchantId, customerId);
    importObjects = await scrubCustomerImports(client, merchantId, customerId);
    await anonymizeCustomerRow(client, merchantId, customerId);
  });
  await deleteCustomerObjects([...documents, ...importObjects.map((key) => ({ object_key: key, document_type: 'customer_import' }))]);
  await deleteCustomerProjections(merchantId, customerId);
  for (const destination of mailDestinations) {
    try { await deleteMailpitMessagesForRecipient(destination); }
    catch (error) { logger.warn({ error, destination }, 'failed to purge mailpit messages for erased recipient'); }
  }
}"}

