{"security_risk":"LOW","summary":"Create erasure-worker main","command":"create","path":"/workspace/source/apps/erasure-worker/src/main.ts","file_text":"import { randomUUID } from 'node:crypto';
import { processErasure } from './cleanup.js';
import {
  claimErasureRequest,
  markErasureCompleted,
  markErasureFailed,
} from './repository.js';
import { logger } from '../../../packages/observability/src/logger.js';

process.env.SERVICE_NAME = 'erasure-worker';
const workerId = `erasure-worker-${randomUUID()}`;
const controller = new AbortController();

async function run(signal: AbortSignal): Promise<void> {
  while (!signal.aborted) {
    const claimed = await claimErasureRequest(workerId);
    if (!claimed) { await new Promise((resolve) => setTimeout(resolve, 500)); continue; }
    try {
      await processErasure(claimed);
      await markErasureCompleted(claimed.id);
      logger.info({ requestId: claimed.id, merchantId: claimed.merchant_id, customerId: claimed.customer_id }, 'erasure completed');
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const terminal = claimed.attempts >= 5;
      await markErasureFailed(claimed.id, message, terminal);
      logger.error({ error, requestId: claimed.id, terminal }, 'erasure attempt failed');
    }
  }
}

void run(controller.signal);
logger.info({ workerId }, 'erasure worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => controller.abort());"}

