}

function anonymizedDisplayName(customerId: string): string {
  return `Deleted Customer (${anonymizedEmailSuffix(customerId)})`;
}

async function scrubNotificationDestinations(client: pg.PoolClient, merchantId: string, customerId: string): Promise<string[]> {
  const result = await client.query<{ destination: string | null }>(
    `SELECT destination FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL
     UNION
     SELECT destination FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL
     UNION
     SELECT destination FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2 AND destination IS NOT NULL`,
    [merchantId, customerId],
  );
  const destinations = [...new Set(result.rows.map((row) => row.destination).filter((value): value is string => Boolean(value)))];
  await client.query(
    `UPDATE operations.email_deliveries SET destination=NULL WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.notifications SET destination=NULL WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.notification_preferences SET destination=NULL, enabled=false, updated_at=now()
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.analytics_events SET email=NULL WHERE merchant_id=$1 AND customer_id=$2 AND email IS NOT NULL`,
    [merchantId, customerId],
  );
  return destinations;
}

async function redactPendingOutboxPayloads(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE operations.outbox_events
     SET payload=jsonb_build_object('redacted', true, 'reason', 'erasure_in_progress')
     WHERE merchant_id=$1 AND aggregate_id=$2 AND status='pending'
       AND (payload ? 'email' OR payload ? 'customerEmail' OR payload ? 'customerSnapshot'
            OR payload ? 'billingSnapshot' OR payload ? 'destination')`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.outbox_events SET status='cancelled'
     WHERE merchant_id=$1 AND aggregate_id=$2 AND status='pending'
       AND event_type IN ('customer.created.v1','customer.updated.v1','customer.deleted.v1',
                          'customer.contact.changed.v1','customer.address.changed.v1',
                          'customer.payment_method.attached.v1','support.message.created.v1',
                          'customer.import.recorded.v1')`,
    [merchantId, customerId],
  );
}

async function redactPendingJobs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE operations.jobs
     SET status='cancelled', available_at=now(), last_error='cancelled_for_erasure'
     WHERE merchant_id=$1 AND status<>'completed'
       AND payload->>'customerId'=$2`,
