     ) AND customer_email IS NOT NULL`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE payments.invoices
     SET billing_snapshot=jsonb_build_object('redacted', true)::jsonb
     WHERE merchant_id=$1 AND customer_id=$2
       AND billing_snapshot IS NOT NULL
       AND NOT (billing_snapshot ? 'redacted')`,
    [merchantId, customerId],
