async function anonymizeCustomerRow(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  const email = anonymizedEmailFor(customerId);
  const externalReference = anonymizedExternalReference(customerId);
  const displayName = anonymizedDisplayName(customerId);
  await client.query(
    `UPDATE customers.customers
     SET email=$3, name=$4, external_reference=$5, phone=NULL,
         metadata='{}'::jsonb, status='deleted', updated_at=now(), version=version+1
     WHERE merchant_id=$1 AND id=$2 AND status<>'deleted'`,
    [merchantId, customerId, email, displayName, externalReference],
  );
}

async function redactAuditLogs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(
    `UPDATE platform.audit_logs
     SET metadata=jsonb_build_object('redacted', true)::jsonb
     WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2
       AND NOT (metadata ? 'redacted')`,
    [merchantId, customerId],
  );
}

async function detachDocumentManifests(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureDocumentObject[]> {
  const listed = await client.query<ErasureDocumentObject>(
    `SELECT object_key, document_type FROM operations.document_manifests
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  await client.query(
    `UPDATE operations.document_manifests SET customer_id=NULL
     WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return listed.rows;
}

async function deleteCustomerObjects(objects: ErasureDocumentObject[]): Promise<void> {
  for (const object of objects) {
    try {
      await objectStore.removeObject(DOCUMENT_BUCKET, object.object_key);
    } catch (error) {
      logger.warn({ error, objectKey: object.object_key }, 'failed to remove erasure document object');
    }
  }
}

async function deleteCustomerProjections(merchantId: string, customerId: string): Promise<void> {
  await redis.del(`merchant:${merchantId}:customer:${customerId}`);
  await redis.del(`merchant:${merchantId}:customer:${customerId}:activity`);
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
  } catch (error) {
    const status = (error as { statusCode?: number }).statusCode;
    if (status !== 404) logger.warn({ error, merchantId, customerId }, 'failed to remove opensearch customer projection');
  }
}

async function redactCustomerImports(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  // customer_imports is per-file, not per-customer, but the imported file can
  // contain customer PII. We rely on the matching document_manifests scrub
  // (handled in detachDocumentManifests) to delete the object from MinIO.
  // Here we only log the link that such imports should be reviewed.
  void merchantId; void customerId;
}

/**
 * Executes the full privacy-aware deletion flow for a single customer inside
 * one transactional boundary, then performs the irreversible external cleanup
 * (MinIO, Redis, OpenSearch, Mailpit). Every step is written to be safely
 * re-runnable: a worker that crashes mid-way will resume on a fresh claim and
 * converge on the same end state without exposing customer data again.
 */
export async function processErasure(request: ClaimedErasure): Promise<void> {
  const { merchant_id: merchantId, customer_id: customerId } = request;
  let documents: ErasureDocumentObject[] = [];
  let mailDestinations: string[] = [];
  await transaction(async (client) => {
    await scrubDirectCustomerTables(client, merchantId, customerId);
    mailDestinations = await scrubNotificationDestinations(client, merchantId, customerId);
    await redactPendingOutboxPayloads(client, merchantId, customerId);
    await redactPendingJobs(client, merchantId, customerId);
    await scrubFinancialRecords(client, merchantId, customerId);
    await scrubSupportData(client, merchantId, customerId);
    await redactAuditLogs(client, merchantId, customerId);
    documents = await detachDocumentManifests(client, merchantId, customerId);
    await redactCustomerImports(client, merchantId, customerId);
    await anonymizeCustomerRow(client, merchantId, customerId);
  });
  await deleteCustomerObjects(documents);
  await deleteCustomerProjections(merchantId, customerId);
  for (const destination of mailDestinations) {
    try { await deleteMailpitMessagesForRecipient(destination); }
    catch (error) { logger.warn({ error, destination }, 'failed to purge mailpit messages for erased recipient'); }
  }
}"}

{"security_risk":"LOW","summary":"Fix claim query to exclude terminal failures","command":"str_replace","path":"/workspace/source/apps/erasure-worker/src/repository.ts","old_str":"/**
 * Atomically claims a single pending or previously-failed erasure request.
 * Uses `FOR UPDATE SKIP LOCKED` so multiple workers can safely cooperate and
 * `processing` rows are immediately rejected by the `status IN ('pending','failed')`
 * predicate, giving every claim a fresh attempt counter.
 */
export async function claimErasureRequest(workerId: string, leaseSeconds = 120): Promise<ClaimedErasure | undefined> {
  return await transaction(async (client) => {
    const result = await client.query<ClaimedErasure>(
      `UPDATE customers.erasure_requests er
       SET status='processing', attempts=attempts+1, updated_at=now(),
           last_error=NULL
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed')
         ORDER BY updated_at
         FOR UPDATE SKIP LOCKED LIMIT 1
       )
       RETURNING id, merchant_id, customer_id, attempts`,
    );
    return result.rows[0];
  });
}","new_str":"/**
 * Atomically claims a single pending or previously-failed erasure request that
 * still has retry budget remaining. Uses `FOR UPDATE SKIP LOCKED` so multiple
 * workers can safely cooperate and `processing` rows are immediately rejected
 * by the `status IN ('pending','failed')` predicate, giving every claim a
 * fresh attempt counter. Rows whose `attempts` already exhausted the retry
 * budget are skipped so a terminally-failed request stops being reprocessed.
 */
export async function claimErasureRequest(workerId: string, leaseSeconds = 120, maxAttempts = 5): Promise<ClaimedErasure | undefined> {
  return await transaction(async (client) => {
    const result = await client.query<ClaimedErasure>(
      `UPDATE customers.erasure_requests er
       SET status='processing', attempts=attempts+1, updated_at=now(),
           last_error=NULL
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed') AND attempts < $2
         ORDER BY updated_at
         FOR UPDATE SKIP LOCKED LIMIT 1
       )
       RETURNING id, merchant_id, customer_id, attempts`,
      [workerId, maxAttempts],
    );
    return result.rows[0];
  });
}"}

